const $=selector=>document.querySelector(selector);
const escapeHTML=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function readSaved(){try{return JSON.parse(localStorage.getItem('eylul-rehber-saved')||'[]')}catch{return []}}
function readStamps(){try{return JSON.parse(localStorage.getItem('eylul-rehber-stamps')||'[]')}catch{return []}}
function stampCount(){return events().filter(e=>state.stamps.has(e.id)).length}
function list(){return state.fair==='ankara'?[...authors,...publishers]:[...childBrands,...childPlaces]}
function events(){return state.fair==='ankara'?[...eventSets.ankara,...bookTalks]:eventSets.children}
let animateNextRender=false;
let routeTransition='page';
let tourNavigationFromScroll=false;
function go(page){const from=state.page;const detail=page==='event'||page==='participant';const leavingDetail=from==='event'||from==='participant';routeTransition=detail&&from!==page?'route-forward':leavingDetail&&!detail?'route-back':'page';animateNextRender=from!==page;state.page=page;state.query='';render();$('#phone').scrollTop=0;$('#scroll-area').scrollTop=0;if(!tourNavigationFromScroll&&window.innerWidth>850){const step=tourOrder.indexOf(page);if(step>=0)window.scrollTo({top:step*window.innerHeight,behavior:'instant'})}}
function pickFair(fair){routeTransition='page';animateNextRender=true;state.fair=fair;state.page='home';state.phase='during';state.day=1;state.kind='Tümü';state.programQuery='';state.category='Tümü';state.query='';state.selectedZone='A12';closeSheet();render();$('#phone').scrollTop=0;$('#scroll-area').scrollTop=0;if(window.innerWidth>850)window.scrollTo({top:window.innerHeight,behavior:'instant'})}
function toast(message){const box=$('#toast');box.textContent=message;box.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>box.classList.remove('show'),2600)}
function hideDemoNotification(){
  clearTimeout(window.pushTimer);
  clearTimeout(window.pushHideTimer);
  clearTimeout(window.pushEntranceTimer);
  const banner=$('#push-notification');
  banner.classList.remove('show');
  $('#phone').classList.remove('is-notifying');
  window.pushHideTimer=setTimeout(()=>{if(!banner.classList.contains('show'))banner.hidden=true},240);
}
let demoNoticeCursor=0;
function showDemoNotification(message){
  const samples=state.fair==='ankara'?[{title:'24. Ankara Kitap Fuarı yaklaşıyor',body:'4–13 Aralık’ta görüşmek üzere. Fuar haberlerini bu rehberden takip et.'},{title:'Örnek: Söyleşi saati güncellendi',body:'İlgilendiğin söyleşinin yeni saatini programdan kontrol et.'},{title:'Örnek: Yeni buluşma duyurusu',body:'Bugünün imza ve söyleşi programına göz at.'}]:[{title:'Çocuk Şenliği duyurusu',body:'Şenlik haberlerini ve etkinlikleri bu rehberden takip et.'},{title:'Örnek: Atölye saati güncellendi',body:'Ailen için seçtiğin atölyenin güncel saatini programdan gör.'},{title:'Örnek: Yeni etkinlik açıldı',body:'Çocuk Şenliği programındaki yeni etkinliğe göz at.'}];
  const notice=message||{...samples[demoNoticeCursor++%samples.length],audience:'Tüm ziyaretçiler'};
  state.demoNotice=notice;
  state.noticeFilter='Tümü';
  if(state.page==='notifications')render();
  const banner=$('#push-notification');
  const wasVisible=!banner.hidden;
  clearTimeout(window.pushTimer);
  clearTimeout(window.pushHideTimer);
  clearTimeout(window.pushEntranceTimer);
  banner.classList.remove('show');
  $('#phone').classList.remove('is-notifying');
  const open=()=>{
    $('#push-title').textContent=notice.title;
    $('#push-body').textContent=notice.body;
    banner.hidden=false;
    void banner.offsetWidth;
    banner.classList.add('show');
    $('#phone').classList.add('is-notifying');
    window.pushTimer=setTimeout(hideDemoNotification,8000);
  };
  if(wasVisible)window.pushEntranceTimer=setTimeout(open,320);
  else open();
}
function nav(){document.querySelectorAll('.bottom-nav button').forEach(button=>button.classList.toggle('active',button.dataset.page===state.page||((state.page==='event'||state.page==='participant')&&button.dataset.page===state.previous)||(state.page==='passport'&&button.dataset.page==='home')))}
function render(){const photoDetail=state.fair==='ankara'&&((state.page==='event'&&(authors.some(a=>a.name===events().find(e=>e.id===state.detail)?.title)||bookTalks.some(e=>e.id===state.detail)))||(state.page==='participant'&&authors.some(a=>a.id===state.detail)));$('#phone').classList.toggle('detail-open',state.page==='event'||state.page==='participant');$('#phone').classList.toggle('photo-detail',photoDetail);const pages={welcome,home,program,map,discover,plan,notifications,admin,passport,event:eventDetail,participant:participantDetail,about};$('#screen').innerHTML=pages[state.page]();if(animateNextRender){$('#screen>.screen')?.classList.add('route-enter',routeTransition);animateNextRender=false}nav();updatePresentation()}
function photoClass(){return state.fair==='children'?' children':''}
function chooseButton(){return `<button class="selector" data-action="switch-fair"><span><small>SEÇİLİ FUAR</small><strong>${fairs[state.fair].name}</strong></span><span class="chev">⌄</span></button>`}
function sectionTitle(title,page,label='Tümünü gör →'){return `<div class="section-title"><h2>${title}</h2>${page?`<button class="link-button" data-page="${page}">${label}</button>`:''}</div>`}
function welcome(){return `<div class="screen tight welcome-screen"><div class="kicker">EYLÜL FUAR REHBERİ</div><h1 class="page-title">Fuarını seç.</h1><div class="welcome-photo"><div class="archive-badge">Eylül Fuarcılık arşivi</div><div class="welcome-content"><div class="kicker" style="color:#ffb94b">TEK REHBER, TÜM FUARLAR</div><h1>Fuardaki her şey<br>cebinde.</h1></div></div><button class="event-choice" data-pick-fair="ankara"><span class="thumb"></span><span><strong>24. Ankara Kitap Fuarı</strong><small>4–13 Aralık 2026 · Planlanan tarih</small></span><span class="arrow">→</span></button><button class="event-choice" data-pick-fair="children"><span class="thumb children"></span><span><strong>Çocuk Şenliği</strong><small>Aile ve çocuk · Konsept görünümü</small></span><span class="arrow">→</span></button><button class="link-button" data-page="about" style="margin:5px 0 0">Eylül Fuarcılık hakkında →</button></div>`}
function home(){const book=state.fair==='ankara';return `<div class="screen tight home-screen">${chooseButton()}${hero(book?'Kitap fuarı<br>cebinde.':'Şenlik rehberi<br>cebinde.',book?'İmzalar, söyleşiler ve yayınevleri bir arada.':'Program, markalar ve alanlar tek yerde.',book?'İmza programını gör':'Programı aç','open-program')}<div class="home-shortcuts">${book?'<button class="home-shortcut" data-action="open-signings"><span>✎</span><strong>İmzalar</strong></button><button class="home-shortcut" data-action="open-talks"><span>◉</span><strong>Söyleşiler</strong></button><button class="home-shortcut" data-page="discover"><span>▤</span><strong>Yayınevleri</strong></button>':'<button class="home-shortcut" data-page="discover"><span>⌕</span><strong>Markalar</strong></button><button class="home-shortcut" data-page="map"><span>⌖</span><strong>Harita</strong></button><button class="home-shortcut" data-page="plan"><span>♡</span><strong>Planım</strong></button>'}</div><button class="notice-banner" data-page="notifications"><span class="ping">!</span><span><strong>Eylül’den duyurular</strong><span>Önemli değişiklikleri burada gör</span></span><span class="notice-arrow">→</span></button><p class="context-note">${book?'İmzalar 2025 arşivinden; söyleşiler 2026 deneyimini gösteren örneklerdir.':'Çocuk Şenliği programı ve markalar sunum için hazırlanmış örneklerdir.'}</p>${sectionTitle(book?'2025’ten bir imza':'Örnek etkinlik','program')}${eventCard(events()[0])}${sectionTitle(book?'Yayınevleri':'Örnek markalar','discover')}${brandStrip()}</div>`}
function hero(title,subtitle,button,action){return `<div class="hero-photo${photoClass()}">${state.fair==='ankara'?'<div class="archive-badge">2026 konsept görseli</div>':''}<div class="hero-content"><div class="hero-label">${fairs[state.fair].name.toLocaleUpperCase('tr')}</div><h2>${title}</h2><p>${subtitle}</p><div class="hero-actions"><button data-action="${action}">${button} →</button></div></div></div>`}
function beforeHome(fair){return `${hero('Fuar gününü<br>kendine göre planla.','İlgi alanlarını seç, programını oluştur ve giriş bilgilerini cebinde tut.','Programı incele','open-program')}${sectionTitle('Gelmeden önce')}<div class="quick-grid"><button class="quick-tile" data-action="ticket"><span class="tile-icon">▣</span><strong>Bilet & giriş</strong><small>Giriş bilgilerini gör</small></button><button class="quick-tile" data-action="venue"><span class="tile-icon">⌖</span><strong>Ulaşım</strong><small>${escapeHTML(fair.venue)}</small></button><button class="quick-tile" data-page="program"><span class="tile-icon">▤</span><strong>Program</strong><small>Etkinlikleri kaydet</small></button><button class="quick-tile" data-page="notifications"><span class="tile-icon">◉</span><strong>Hatırlatmalar</strong><small>Bildirim tercihleri</small></button></div>${sectionTitle('Yayınevlerini keşfet','discover')}${brandStrip()}${organizerCard()}`}
function duringHome(fair){return `${hero('Bugün fuarda<br>neler var?','Saatlik programı takip et, katılımcıları bul ve stantlara kolayca ulaş.','Şimdi keşfet','open-program')}<div class="mini-status"><span>●</span><span><strong>Canlı rehber fikri</strong> · Program, stant ve duyurular tek ekranda.</span></div><button class="notice-banner" data-page="notifications"><span class="ping">!</span><span><strong>Duyuruları kaçırma</strong><span>Program değişiklikleri ve kayıtlı etkinlik uyarıları</span></span><span style="margin-left:auto;color:#f3a126">→</span></button><div class="quick-grid"><button class="quick-tile" data-page="program"><span class="tile-icon">▤</span><strong>Etkinlik programı</strong><small>Güne göre filtrele</small></button><button class="quick-tile" data-page="discover"><span class="tile-icon">⌕</span><strong>Katılımcı bul</strong><small>Yayınevi ve stant ara</small></button><button class="quick-tile" data-page="map"><span class="tile-icon">⌖</span><strong>Salon krokisi</strong><small>Alanları keşfet</small></button><button class="quick-tile" data-action="qr"><span class="tile-icon">▦</span><strong>QR ile keşfet</strong><small>Standı okut</small></button></div>${sectionTitle('Sıradaki etkinlikler','program')}${events().filter(e=>e.day===1).slice(0,3).map(eventCard).join('')}${sectionTitle('Katılımcılar','discover')}${brandStrip()}${sectionTitle('Fuar içi hizmetler')}${serviceRow()}${organizerCard()}`}
function afterHome(){const count=events().filter(event=>state.saved.has(event.id)).length;return `${hero('Günün izleri<br>seninle kalsın.','Kaydettiğin buluşmaları gör, deneyimini paylaş ve diğer fuarları keşfet.','Planımı gör','open-plan')}<div class="plan-summary"><span>Bugünkü planın<br><strong>${count}</strong> <span>kayıtlı etkinlik</span></span><span style="font-size:27px;color:#f7a021">↗</span></div><div class="quick-grid"><button class="quick-tile" data-page="plan"><span class="tile-icon">♡</span><strong>Planıma dön</strong><small>Kaydettiklerin</small></button><button class="quick-tile" data-action="feedback"><span class="tile-icon">✦</span><strong>Görüşünü paylaş</strong><small>Demo geri bildirim</small></button><button class="quick-tile" data-page="welcome"><span class="tile-icon">◫</span><strong>Diğer fuarlar</strong><small>Yeni deneyimler</small></button><button class="quick-tile" data-page="about"><span class="tile-icon">ⓘ</span><strong>Organizatör</strong><small>Eylül Fuarcılık</small></button></div>${organizerCard()}`}
function brandStrip(){const items=state.fair==='ankara'?publishers:childBrands;return `<div class="brand-strip">${items.map(p=>`<button class="brand-card" data-participant="${p.id}"><span class="brand-logo-wrap"><img class="brand-logo" src="assets/${p.logo}" alt="${escapeHTML(p.name)} logosu"></span><small>${escapeHTML(p.name)}<br><b>Profili gör →</b></small></button>`).join('')}</div>`}
function organizerCard(){return `<div class="organizer-card"><img src="assets/eylul-fuarcilik-logo.png" alt="Eylül Fuarcılık"><p>1999'dan beri kitap ve eğitim fuarları düzenleyen Eylül Fuarcılık'ı tanı.</p><button data-page="about">Organizatörü tanı →</button></div>`}
function serviceRow(){return `<div class="service-row"><button data-service="Danışma"><span>ⓘ</span>Danışma</button><button data-service="WC"><span>♧</span>WC</button><button data-service="Dinlenme"><span>☕</span>Dinlenme</button><button data-service="İlk yardım"><span>✚</span>İlk yardım</button><button data-service="Çıkış"><span>➜</span>Çıkış</button></div><p class="muted-note">Hizmet konumları resmî fuar planıyla doğrulanınca haritaya eklenir.</p>`}
function eventCard(event){const book=state.fair==='ankara';const talk=book&&event.kind==='Söyleşi';return `<div class="event-card ${talk?'talk-card':''}"><div class="event-time">${event.time}</div><div class="event-copy" data-event="${event.id}" role="button" tabindex="0"><small>${talk?'ÖRNEK SÖYLEŞİ':book?`${event.date} · ${event.kind}`:`${event.kind} · ${event.age}`}</small><strong>${escapeHTML(event.title)}</strong><span>${talk?escapeHTML(event.place):book?escapeHTML(event.publisher):escapeHTML(event.place)} · Detayı gör →</span></div><button class="save-btn ${state.saved.has(event.id)?'saved':''}" data-save="${event.id}" aria-label="${state.saved.has(event.id)?'Planımdan çıkar':'Planıma ekle'}">${state.saved.has(event.id)?'♥':'♡'}</button></div>`}
function programItems(){
  const book=state.fair==='ankara';
  const pool=book?(state.kind==='Söyleşi'?bookTalks:eventSets.ankara):eventSets.children;
  const query=state.programQuery.trim().toLocaleLowerCase('tr');
  return pool.filter(e=>e.day===state.day&&(book||state.kind==='Tümü'||e.kind===state.kind)).filter(e=>!book||!query||[e.title,e.publisher,e.host,e.speaker,e.place,e.description].join(' ').toLocaleLowerCase('tr').includes(query));
}
function programResults(){const visible=programItems();return visible.length?visible.map(eventCard).join(''):'<div class="empty">Bu gün için eşleşen etkinlik bulunamadı.</div>'}
function program(){
  const book=state.fair==='ankara';
  const talks=book&&state.kind==='Söyleşi';
  const kinds=['Tümü',...new Set(eventSets.children.map(e=>e.kind))];
  return `<div class="screen program-screen"><div class="kicker">${fairs[state.fair].name.toLocaleUpperCase('tr')}</div><h1 class="page-title">${book?'Fuar programı':'Etkinlik programı'}</h1><p class="page-sub">${book?'İmza günlerini ve söyleşileri ayrı ayrı keşfet.':'Gününü seç, ilgilendiğin etkinlikleri planına ekle.'}</p>${book?`<div class="book-program-tabs"><button class="${talks?'':'active'}" data-kind="İmza">✎ İmza günleri</button><button class="${talks?'active':''}" data-kind="Söyleşi">◉ Söyleşiler</button></div><div class="archive-callout"><strong>${talks?'Örnek söyleşi akışı':'2025 imza arşivi'}</strong><span>${talks?'Konular ve saatler tasarım örneğidir. 2026 söyleşi programı açıklanınca gerçek kayıtlarla değişir.':'Buradaki imzalar resmî 2025 arşivinden. 2026 programı yayımlanınca yenilenir.'}</span></div><input id="program-search" class="search" type="search" value="${escapeHTML(state.programQuery)}" placeholder="Bu günde yazar veya konu ara" aria-label="Programda ara">`:'<div class="archive-callout"><strong>Örnek Çocuk Şenliği programı</strong><span>Tarih, katılımcı ve etkinlikler Eylül tarafından doğrulanınca güncellenir.</span></div>'}<div class="chip-row">${[1,2,3].map(d=>`<button class="chip ${state.day===d?'active':''}" data-day="${d}">${book&&!talks?["10 Eki","11 Eki","12 Eki"][d-1]:`${d}. gün`}</button>`).join('')}</div>${!book?`<div class="chip-row" style="margin-top:-4px">${kinds.map(k=>`<button class="chip ${state.kind===k?'active':''}" data-kind="${k}">${k}</button>`).join('')}</div>`:''}<div id="event-results">${programResults()}</div><button class="ghost full" data-page="plan" style="margin-top:12px">Kaydettiklerimi gör →</button></div>`;
}
function map(){if(state.fair==='ankara')return `<div class="screen"><div class="kicker">FUAR ALANI</div><h1 class="page-title">Salon krokisi</h1><p class="page-sub">Giriş, koridorlar ve stant düzenini tek yerden incele.</p><div class="archive-callout"><strong>Resmî 23. fuar krokisi · Nisan 2026</strong><span>24. fuarın Aralık 2026 krokisi yayımlanınca bu alan güncellenir.</span></div><button class="real-map-card" data-action="open-map" aria-label="Resmî krokini büyüt"><img src="assets/ankara-resmi-kroki.jpg" alt="Nisan 2026 Ankara Kitap Fuarı resmî salon krokisi"><span>Dokun ve büyüt ↗</span></button><div class="map-panel"><div class="kicker">FUARDA YOLUNU BUL</div><strong>Krokiden standa</strong><p>Canlı sürümde yayınevini aradığında standı bu planda işaretlenecek. Giriş ve hizmet noktaları da tek dokunuşla açılacak.</p><button class="primary dark" data-page="discover">Yayınevi ara →</button></div>${sectionTitle('Fuar içi hizmetler')}${serviceRow()}</div>`;const people=list();const selected=zones[state.selectedZone];const occupant=people.find(p=>p.stand===state.selectedZone);return `<div class="screen"><div class="kicker">FUAR İÇİNDE</div><h1 class="page-title">Salon haritası</h1><p class="page-sub">Bir alana dokunup alanları keşfet.</p><div class="map-card"><div class="map-grid"><button data-zone="A12">A12</button><div class="path">KORİDOR</div><button data-zone="A14">A14</button><button data-zone="B05">B05</button><div class="path">KORİDOR</div><button data-zone="B08">B08</button><button class="service" data-zone="SAHNE">ANA<br>SAHNE</button><button class="service" data-zone="GIRIS">GİRİŞ<br>DANIŞMA</button><button data-zone="C03">C03</button></div></div><div class="map-panel"><div class="kicker">${selected.name}</div><strong>${occupant?occupant.name:selected.type}</strong><p>${occupant?occupant.description:'Bu alan konsept krokide gösteriliyor.'}</p></div></div>`}
function participantCards(items){return items.length?items.map(p=>`<button class="participant-card" data-participant="${p.id}">${p.photo?`<img class="participant-photo" src="assets/${p.photo}" alt="${escapeHTML(p.name)} fotoğrafı">`:p.logo?`<span class="participant-logo"><img src="assets/${p.logo}" alt="${escapeHTML(p.name)} logosu"></span>`:`<span class="participant-mark">${escapeHTML(p.initial.slice(0,2))}</span>`}<span><strong>${escapeHTML(p.name)}</strong><small>${state.fair==='ankara'?`${p.category} · ${escapeHTML(p.publisher||'2025 imza arşivi')}`:p.category==='Marka'?'Örnek marka profili · Katılım teyitli değil':`${p.category} · Temsili alan ${p.stand}`}</small></span><span class="arrow">→</span></button>`).join(''):'<div class="empty">Aramana uygun sonuç bulunamadı.</div>'}
function discover(){const book=state.fair==='ankara';const categories=book?['Tümü','Yayınevi','Yazar']:['Tümü','Marka','Etkinlik','Atölye'];return `<div class="screen discover-screen"><div class="kicker">${book?'YAZAR & YAYINEVİ':'ÇOCUK ŞENLİĞİ'}</div><h1 class="page-title">Neyi arıyorsun?</h1><p class="page-sub">${book?'Yazar veya yayınevini bul.':'Marka, etkinlik veya alanı bul.'}</p><p class="context-note">${book?'2025 imza arşivi':'Marka profilleri örnektir; katılım teyitli değildir.'}</p><input id="search" class="search" type="search" value="${escapeHTML(state.query)}" placeholder="${book?'Yazar veya yayınevi ara':'Marka veya alan ara'}" aria-label="Katılımcı ara"><div class="chip-row">${categories.map(c=>`<button class="chip ${state.category===c?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><div id="participant-results">${participantCards(filteredParticipants())}</div><button class="qr-tile" data-action="qr"><span class="qr-icon">▦</span><span><strong>QR ile profil aç</strong><small>Katılımcı sayfasına doğrudan git</small></span><b>→</b></button></div>`}
function filteredParticipants(){return list().filter(p=>(state.category==='Tümü'||p.category===state.category)&&(p.name+' '+(p.stand||'')+' '+p.category+' '+(p.publisher||'')).toLocaleLowerCase('tr').includes(state.query.toLocaleLowerCase('tr')))}
function plan(){const chosen=events().filter(e=>state.saved.has(e.id));return `<div class="screen"><div class="kicker">KİŞİSEL FUAR AKIŞI</div><h1 class="page-title">Benim planım</h1><p class="page-sub">Merak ettiğin buluşmalar hep elinin altında.</p><div class="plan-summary"><span>Kaydedilen etkinlik<br><strong>${chosen.length}</strong></span><span style="font-size:28px;color:#f2a026">♡</span></div>${chosen.length?chosen.map(eventCard).join(''):'<div class="empty">Henüz etkinlik kaydetmedin.<br>Programdaki kalp simgesiyle planını oluştur.</div>'}<button class="primary full" data-page="program" style="margin:13px 0 10px">Programı keşfet →</button><button class="notification-card" data-page="notifications" style="width:100%;text-align:left;color:inherit"><span class="nicon">◉</span><span><strong>Etkinlik hatırlatmaları</strong><p>Kaydettiklerin yaklaşırken haber al.</p></span></button><p class="muted-note">Plan bu tarayıcıda saklanır. Gerçek hatırlatmalar için bildirim altyapısı ve ziyaretçi izni gerekir.</p></div>`}
function notifications(){
  const samples=[
    {kind:'Önemli',icon:'!',title:'Tüm ziyaretçilere',body:'Giriş, ulaşım ve alan değişiklikleri burada anında görünür.',meta:'GENEL DUYURU · ÖRNEK'},
    {kind:'Önemli',icon:'↗',title:'Program güncellendi',body:'Saat veya salon değiştiğinde güncel bilgi tek yerde.',meta:'PROGRAM DEĞİŞİKLİĞİ · ÖRNEK'},
    {kind:'Planım',icon:'♡',title:'Kaydettiğin etkinlik yaklaşıyor',body:'Planındaki buluşmadan önce sana özel hatırlatma.',meta:'KİŞİSEL HATIRLATMA · ÖRNEK'}
  ];
  if(state.demoNotice)samples.unshift({kind:'Önemli',icon:'◉',title:state.demoNotice.title,body:state.demoNotice.body,meta:state.demoNotice.audience.toLocaleUpperCase('tr')+' · DEMO ÖNİZLEME'});
  const visible=samples.filter(item=>state.noticeFilter==='Tümü'||item.kind===state.noticeFilter);
  return `<div class="screen"><div class="kicker">FUARIN NABZI</div><h1 class="page-title">Bildirimler</h1><p class="page-sub">Herkese açık duyurular ve planına özel haberler tek yerde.</p><div class="chip-row">${['Tümü','Önemli','Planım'].map(filter=>`<button class="chip ${state.noticeFilter===filter?'active':''}" data-notice-filter="${filter}">${filter}</button>`).join('')}</div>${visible.map(item=>`<div class="notification-card"><span class="nicon">${item.icon}</span><span><strong>${escapeHTML(item.title)}</strong><p>${escapeHTML(item.body)}</p><small>${escapeHTML(item.meta)}</small></span></div>`).join('')}${sectionTitle('Bildirim tercihlerim')}<div class="toggle-row"><span><strong>Etkinlik hatırlatmaları</strong><small>Planıma eklediklerim</small></span><button class="switch ${state.prefs.event?'on':''}" data-pref="event" aria-label="Etkinlik hatırlatmalarını aç veya kapat" aria-pressed="${state.prefs.event}"></button></div><div class="toggle-row"><span><strong>Program değişiklikleri</strong><small>Saat ve yer güncellemeleri</small></span><button class="switch ${state.prefs.change?'on':''}" data-pref="change" aria-label="Program değişikliklerini aç veya kapat" aria-pressed="${state.prefs.change}"></button></div><div class="toggle-row"><span><strong>Genel duyurular</strong><small>Fuar içi önemli bilgiler</small></span><button class="switch ${state.prefs.general?'on':''}" data-pref="general" aria-label="Genel duyuruları aç veya kapat" aria-pressed="${state.prefs.general}"></button></div><button class="primary full" data-action="simulate-notification" style="margin-top:13px">◉ Örnek bildirimi üstte göster</button><button class="ghost full" data-page="admin" style="margin-top:9px">Organizatör duyuru önizlemesi →</button><p class="muted-note">Bu test bildirimi telefon ekranında yaklaşık 8 saniye görünür. Gerçek cihaz bildirimi için ziyaretçi izni ve gönderim altyapısı gerekir.</p></div>`;
}
function authorHero(p,label){return `<div class="author-hero ${p.id==='gazalci'?'portrait-hero':''}"><img src="assets/${p.photo}" alt="${escapeHTML(p.name)} fotoğrafı"><div class="author-hero-overlay"><small>${label}</small><h1>${escapeHTML(p.name)}</h1><span>${escapeHTML(p.publisher)}</span></div></div>`}
function bookFeature(p){return `<div class="section-title"><h2>Kitaplarından biri</h2></div><div class="author-book-card"><div class="book-cover-wrap"><img src="assets/${p.bookCover}" alt="${escapeHTML(p.bookTitle)} kitap kapağı"></div><div><small>YAZARIN KİTABI</small><strong>${escapeHTML(p.bookTitle)}</strong><span>${escapeHTML(p.publisher)}</span></div></div>`}
function eventDetail(){const e=events().find(x=>x.id===state.detail);if(!e)return program();const book=state.fair==='ankara';const talk=book&&e.kind==='Söyleşi';const author=book&&!talk?authors.find(a=>a.name===e.title):null;return `<div class="screen detail-screen ${author||talk?'has-hero':''}"><button class="detail-back" data-page="program" aria-label="Programa dön"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14.5 5-7 7 7 7"/></svg></button>${author?authorHero(author,'2025 İMZA ARŞİVİ'):talk?`<div class="talk-hero"><div><small>ÖRNEK SÖYLEŞİ · KİTAP FUARI</small><h1>${escapeHTML(e.title)}</h1><span>${escapeHTML(e.place)}</span></div></div>`:`<div class="kicker">${book?'2025 İMZA ARŞİVİ':`${e.kind.toLocaleUpperCase('tr')} · ${e.age}`}</div><h1 class="page-title">${escapeHTML(e.title)}</h1>`}${author||talk?'':`<p class="page-sub detail-sub">${book?escapeHTML(e.publisher):escapeHTML(e.speaker)}</p>`}<div class="info-list"><div class="info-line"><span>◷</span><span><strong>Ne zaman?</strong><em>${book?(talk?`${e.day}. gün · örnek saat`:e.date):`${e.day}. gün`} · ${e.time}</em></span></div><div class="info-line"><span>⌖</span><span><strong>Nerede?</strong><em>${escapeHTML(e.place)}</em></span></div>${talk?`<div class="info-line"><span>♙</span><span><strong>Konuşmacı</strong><em>${escapeHTML(e.speaker)}</em></span></div><div class="info-line"><span>▤</span><span><strong>Yayınevi / düzenleyen</strong><em>${escapeHTML(e.host)}</em></span></div>`:''}</div>${author?`<button class="author-inline-link" data-participant="${author.id}">Yazarı tanı <span>→</span></button>${bookFeature(author)}`:talk?`<p class="talk-description">${escapeHTML(e.description)}</p><div class="talk-demo-note">Bu söyleşi yalnızca arayüz örneğidir; resmî programda yer almıyor.</div>`:book?'':`<p class="page-sub">${escapeHTML(e.description)}</p>`}<div class="sheet-actions"><button class="primary" data-save="${e.id}">${state.saved.has(e.id)?'Planımdan çıkar':'♡ Planıma ekle'}</button><button class="ghost" data-page="map">Krokiyi gör →</button></div>${!book?`<button class="passport-banner" data-action="event-qr"><span class="passport-icon">▦</span><span><strong>Bu etkinliğe katıldın mı?</strong><small>Etkinlikteki QR koduyla pasaportuna damga ekle.</small></span><b>→</b></button>`:''}</div>`}
function participantDetail(){const p=list().find(x=>x.id===state.detail);if(!p)return discover();const book=state.fair==='ankara';const related=book?events().filter(e=>e.title===p.name||e.publisher===p.name).slice(0,3):[];if(p.category==='Yazar')return `<div class="screen detail-screen has-hero"><button class="detail-back" data-page="discover" aria-label="Yazarlara dön"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14.5 5-7 7 7 7"/></svg></button>${authorHero(p,'YAZAR · 2025 FUAR ARŞİVİ')}<p class="author-description">${escapeHTML(p.description)}</p>${bookFeature(p)}${related.length?`${sectionTitle('İmza buluşması','program')}${related.map(eventCard).join('')}`:''}</div>`;if(p.category==='Marka')return `<div class="screen detail-screen brand-detail"><button class="detail-back" data-page="discover" aria-label="Markalara dön"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14.5 5-7 7 7 7"/></svg></button><div class="brand-detail-head"><span class="kicker">ÖRNEK MARKA PROFİLİ</span><img src="assets/${p.logo}" alt="${escapeHTML(p.name)} logosu"></div><h1 class="page-title">${escapeHTML(p.name)}</h1><p class="page-sub">${escapeHTML(p.description)}</p><div class="brand-demo-notice">Bu profil iş birliği fikrini göstermek içindir. ${escapeHTML(p.name)} bu şenliğin teyitli sponsoru değildir.</div><div class="section-title"><h2>Şenlikte neler olabilir?</h2></div><div class="brand-offer"><small>MARKAYA ÖZEL ALAN · ÖRNEK</small><strong>${escapeHTML(p.demoOffer)}</strong><span>${p.demoCode?'Ziyaretçi uygulamada kendine özel kodu görebilir.':'Ziyaretçi etkinliği ve marka bilgisini tek yerden görebilir.'}</span>${p.demoCode?`<div class="demo-code"><b>${escapeHTML(p.demoCode)}</b><small>DEMO KODU · GEÇERLİ DEĞİL</small></div>`:''}</div><a class="ghost full brand-website" href="${p.website}" target="_blank" rel="noopener noreferrer">Resmî web sitesi ↗</a><div class="section-title"><h2>Profilde başka ne olur?</h2></div><div class="info-list"><div class="info-line"><span>⌖</span><span><strong>Stand ve konum</strong><em>Kesinleşince fuar haritasına bağlanır.</em></span></div><div class="info-line"><span>◉</span><span><strong>Etkinlik ve duyurular</strong><em>İlgilenen ziyaretçi marka haberlerini takip eder.</em></span></div></div></div>`;return `<div class="screen detail-screen"><button class="detail-back" data-page="discover" aria-label="Rehbere dön"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14.5 5-7 7 7 7"/></svg></button>${p.logo?`<div class="publisher-detail-logo"><img src="assets/${p.logo}" alt="${escapeHTML(p.name)} logosu"></div>`:`<div class="participant-feature" style="height:145px"><small>${p.category.toLocaleUpperCase('tr')}</small><strong>${escapeHTML(p.name)}</strong></div>`}<div class="kicker">${book?'2025 İMZA ARŞİVİ':'KONSEPT ALAN'}</div><h1 class="page-title" style="font-size:24px;margin-top:7px">${escapeHTML(p.name)}</h1><p class="page-sub">${escapeHTML(p.description)}</p>${related.length?`${sectionTitle('İlgili imzalar','program')}${related.map(eventCard).join('')}`:''}${p.website?`<a class="ghost full brand-website" href="${p.website}" target="_blank" rel="noopener noreferrer">Yayınevinin web sitesi ↗</a>`:''}<button class="ghost full" data-page="map" style="margin-top:13px">Salon krokisi →</button></div>`}
function about(){return `<div class="screen"><button class="link-button" data-page="home" style="padding:0;margin-bottom:14px">← Fuara dön</button><img src="assets/eylul-fuarcilik-logo.png" alt="Eylül Fuarcılık" style="width:183px;height:auto;margin:6px 0 18px"><div class="kicker">FUARIN ARKASINDAKİ EKİP</div><h1 class="page-title">Bir araya<br>getiren deneyim.</h1><p class="page-sub" style="font-size:13px;line-height:1.6">Eylül Fuarcılık, Rem Fuar & Organizasyon ile 1999'dan bu yana kitap ve eğitim fuarları düzenliyor. Bu rehber, o fuar deneyimini ziyaretçinin cebine taşıyan bir tasarım önerisi.</p><div class="about-stat"><strong>1999</strong><span>Fuar ve organizasyon yolculuğunun başlangıcı</span></div><div class="detail-hero"><div><h1>İnsanları ve<br>hikâyeleri buluşturur.</h1><p>Eylül Fuarcılık · 20. Ankara Kitap Fuarı arşivi</p></div></div>${sectionTitle('Ziyaretçi için tek adres')}<div class="info-list"><div class="info-line"><span>▤</span><span><strong>Program ve kişisel plan</strong><em>Saat, yer ve etkinlik detayları</em></span></div><div class="info-line"><span>⌖</span><span><strong>Katılımcı ve alan rehberi</strong><em>Arama, stant profili ve kroki</em></span></div><div class="info-line"><span>◉</span><span><strong>Doğrudan bilgilendirme</strong><em>Genel duyuru ve kişisel hatırlatma</em></span></div><div class="info-line"><span>✳</span><span><strong>Fuar Pasaportu</strong><em>İsteğe bağlı etkinlik keşfi</em></span></div></div><button class="primary full" data-page="admin">Organizatör duyuru görünümü →</button><a href="https://eylulfuar.com.tr/kurumsal/hakkimizda" target="_blank" rel="noopener" class="ghost full about-official">Eylül Fuarcılık resmî sitesi ↗</a><p class="muted-note">Kurumsal bilgi ve fotoğraf: Eylül Fuarcılık resmî sitesi. Bu ekran iş birliği için hazırlanmış konsepttir.</p></div>`}
function openSheet(content){$('#sheet').innerHTML=`<div class="sheet-top"><div class="kicker">EYLÜL FUAR REHBERİ</div><button data-action="close-sheet" aria-label="Kapat">×</button></div>${content}`;$('#sheet-backdrop').hidden=false}
function closeSheet(){stopCamera();$('#sheet-backdrop').hidden=true}
function fairSheet(){openSheet(`<h2>Fuarını seç</h2><p>Her fuarın programı, katılımcıları ve haritası kendi içinde açılır.</p><button class="event-choice" data-pick-fair="ankara"><span class="thumb"></span><span><strong>24. Ankara Kitap Fuarı</strong><small>4–13 Aralık 2026</small></span><span class="arrow">→</span></button><button class="event-choice" data-pick-fair="children"><span class="thumb children"></span><span><strong>Çocuk Şenliği</strong><small>Konsept görünümü</small></span><span class="arrow">→</span></button>`)}
function openMapSheet(){openSheet(`<h2>Resmî fuar krokisi</h2><p>3–12 Nisan 2026 tarihli 23. Ankara Kitap Fuarı salon planı. Yaklaşan fuarın planı ayrıca yayımlanacaktır.</p><div class="map-zoom"><img src="assets/ankara-resmi-kroki.jpg" alt="2026 Nisan resmî fuar krokisi"></div>`)}
function helpSheet(){openSheet(`<h2>Nasıl yardımcı olabiliriz?</h2><p>Fuar alanında en çok aranan bilgilere buradan ulaşabilirsin.</p><div class="info-list"><div class="info-line"><span>⌖</span><span><strong>Yer ve stantlar</strong><em>Harita sekmesinden ara.</em></span></div><div class="info-line"><span>◷</span><span><strong>Etkinlik saatleri</strong><em>Program sekmesinden takip et.</em></span></div><div class="info-line"><span>ⓘ</span><span><strong>Organizatör</strong><em>Eylül Fuarcılık</em></span></div></div><div class="sheet-actions"><button class="primary" data-page="map">Haritaya git</button><button class="ghost" data-page="about">Hakkımızda</button></div>`)}
function ticketSheet(){openSheet(`<h2>Giriş & bilet</h2><p>Giriş bilgilerini bu alanda görebilirsin. ${state.fair==='ankara'?'Ankara Kitap Fuarı için mevcut e-bilet sayfasına geçiş aşağıda.':'Çocuk Şenliği için resmî bilet ve giriş bilgileri henüz eklenmedi.'}</p>${state.fair==='ankara'?'<a class="primary" href="https://ankarakitapfuari.org.tr/biletler" target="_blank" rel="noopener" style="display:inline-block">Resmî e-bilet sayfası →</a>':''}<p class="muted-note">Bu demo bilet satışı veya giriş doğrulaması yapmaz.</p>`)}
function venueSheet(){openSheet(`<h2>Ulaşım</h2><p>${state.fair==='ankara'?'Önceki Ankara Kitap Fuarı ATO Congresium’da yapıldı. Yaklaşan 24. fuarın mekânı organizatör tarafından teyit edilince güncel adres burada gösterilir.':'Çocuk Şenliği mekân bilgisi organizatörden geldikten sonra burada gösterilir.'}</p><div class="info-line"><span>⌖</span><span><strong>${fairs[state.fair].venue}</strong><em>Giriş, otopark ve erişim bilgileri resmî fuar verisiyle eklenir.</em></span></div>`)}
function feedbackSheet(){openSheet(`<h2>Fuar deneyimin nasıldı?</h2><p>Görüşlerin fuar deneyiminin gelişmesine yardımcı olabilir. Bu demo yanıtları herhangi bir yere göndermez.</p><div class="sheet-actions"><button class="ghost" data-rate="1">😐</button><button class="ghost" data-rate="2">🙂</button><button class="ghost" data-rate="3">😍</button></div>`)}
function serviceSheet(name){openSheet(`<h2>${escapeHTML(name)}</h2><p>${escapeHTML(name)} konumu, resmî fuar planı verildiğinde burada harita üzerinde gösterilir.</p><button class="primary" data-page="map">Haritayı aç →</button>`)}
function qrSheet(mode='stand'){
  state.qrMode=mode;
  const isEvent=mode==='event';
  openSheet(`<h2>${isEvent?'Etkinlik QR kodu':state.fair==='ankara'?'Yayınevi QR profili':'Marka veya alanı QR ile keşfet'}</h2><p>${isEvent?'Katıldığın etkinlikteki kodu okut. Bu demoda ETK-A1 gibi örnek kodları deneyebilirsin.':state.fair==='ankara'?'Yayınevi QR kodunu okutarak profile geç. Demo için CAN veya ALFA yaz.':'Marka veya alan kodunu okutarak profile geç. Demo için TOYZZ ya da A12 yaz.'}</p><div class="scan-frame">▦</div><video class="scan-video" id="scan-video" playsinline muted></video><button class="primary full" data-action="start-camera">Kamerayı aç</button><div class="row" style="margin-top:10px"><input class="search" id="qr-code" type="text" placeholder="${isEvent?'Örn. ETK-A1':state.fair==='ankara'?'Örn. CAN':'Örn. TOYZZ veya A12'}" aria-label="${isEvent?'Etkinlik kodu':state.fair==='ankara'?'Yayınevi kodu':'Alan kodu'}" style="margin:0;flex:1;min-width:0"><button class="ghost" data-action="lookup-code">${isEvent?'Damga ekle':'Bul'}</button></div><p class="muted-note">${isEvent?'Örnek kodlar: '+events().slice(0,3).map(e=>'ETK-'+e.id.toUpperCase()).join(', ')+'. Gerçek katılım doğrulaması için organizatörün etkinliğe özel güvenli QR kodları gerekir.':state.fair==='ankara'?'Demo yayınevi kodları: CAN, DOGAN, ALFA, EVEREST. Gerçek QR bağlantıları organizatör verisiyle kurulur.':'Demo kodları: TOYZZ, APTAMIL, A12, A14, B05, B08.'}</p>`)
}
function save(id){state.saved.has(id)?state.saved.delete(id):state.saved.add(id);localStorage.setItem('eylul-rehber-saved',JSON.stringify([...state.saved]));render();toast(state.saved.has(id)?'Planına eklendi':'Planından çıkarıldı')}
function showEvent(id){state.detail=id;state.previous='program';go('event')}
function showParticipant(id){state.detail=id;state.previous='discover';go('participant')}
function showZone(zone){state.selectedZone=zone;closeSheet();go('map')}
function lookupCode(){
  const code=$('#qr-code')?.value.trim().toUpperCase();
  if(!code)return toast('Bir kod gir.');
  if(state.qrMode==='event'){
    const id=code.replace(/^ETK-/, '').toLowerCase();
    const found=events().find(e=>e.id===id && code==='ETK-'+e.id.toUpperCase());
    if(!found)return toast('Bu etkinlik kodu demo listesinde yok.');
    const already=state.stamps.has(id);
    state.stamps.add(id);
    localStorage.setItem('eylul-rehber-stamps',JSON.stringify([...state.stamps]));
    closeSheet();go('passport');
    return toast(already?'Bu etkinliğin damgası zaten pasaportunda.':'Etkinlik damgası pasaportuna eklendi.');
  }
  const person=state.fair==='ankara'?publishers.find(p=>p.id.toUpperCase()===code):list().find(p=>p.stand===code||p.id.toUpperCase()===code);
  if(person){closeSheet();showParticipant(person.id)}else toast('Bu kod demo listesinde bulunamadı.');
}
let cameraStream=null,scanTimer=null;
async function startCamera(){const video=$('#scan-video');if(!video||!navigator.mediaDevices?.getUserMedia){toast('Kamera bu ortamda kullanılamıyor. Kodu yazabilirsin.');return}try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});video.srcObject=cameraStream;video.classList.add('show');await video.play();if('BarcodeDetector' in window){const detector=new BarcodeDetector({formats:['qr_code']});scanTimer=setInterval(async()=>{try{const found=await detector.detect(video);if(found.length){const value=found[0].rawValue;const code=state.qrMode==='event'?value.match(/ETK-(A(?:[0-9]|10|11|12)|C[1-5])/i)?.[0]?.toUpperCase():state.fair==='ankara'?value.match(/\b(CAN|DOGAN|ALFA|EVEREST|ALTIN|KIRMIZI)\b/i)?.[1]?.toUpperCase():value.match(/\b(TOYZZ|APTAMIL|A12|A14|B05|B08|C03|C06)\b/i)?.[1]?.toUpperCase();if(code){$('#qr-code').value=code;lookupCode()}else toast('Demo kodu tanınmadı.')}}catch{}},700)}else toast('Kamera açık. Bu tarayıcıda QR tanıma yok; kodu yazabilirsin.')}catch{toast('Kamera izni alınamadı. Kodu yazabilirsin.')}}
function stopCamera(){if(scanTimer)clearInterval(scanTimer);scanTimer=null;if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null}}
async function enableNotifications(){if(!('Notification' in window)){toast('Bu tarayıcı telefon bildirimlerini desteklemiyor.');return}try{const permission=await Notification.requestPermission();if(permission==='granted'){toast('Bildirim izni verildi.');new Notification('Eylül Fuar Rehberi',{body:'Örnek: Kaydettiğin etkinlik birazdan başlıyor.'})}else toast('Bildirim izni verilmedi.')}catch{toast('Bildirim önizlemesi bu ortamda kullanılamıyor.')}}
document.addEventListener('click',event=>{const el=event.target.closest('button,[data-event]');if(!el)return;if(el.dataset.tour)return moveTour(el.dataset.tour==='next'?1:-1);if(el.dataset.pickFair)return pickFair(el.dataset.pickFair);if(el.dataset.save)return save(el.dataset.save);if(el.dataset.event)return showEvent(el.dataset.event);if(el.dataset.participant)return showParticipant(el.dataset.participant);if(el.dataset.showZone)return showZone(el.dataset.showZone);if(el.dataset.zone){state.selectedZone=el.dataset.zone;return render()}if(el.dataset.phase){state.phase=el.dataset.phase;return render()}if(el.dataset.day){state.day=Number(el.dataset.day);return render()}if(el.dataset.kind){state.kind=el.dataset.kind;if(state.fair==='ankara')state.programQuery='';return render()}if(el.dataset.category){state.category=el.dataset.category;return render()}if(el.dataset.noticeFilter){state.noticeFilter=el.dataset.noticeFilter;return render()}if(el.dataset.adminAudience){state.adminAudience=el.dataset.adminAudience;return render()}if(el.dataset.quiz){state.quizAnswer=el.dataset.quiz;return render()}if(el.dataset.pref){state.prefs[el.dataset.pref]=!state.prefs[el.dataset.pref];return render()}if(el.dataset.rate){closeSheet();state.feedback=true;return toast('Demo geri bildirimin kaydedildi.')}if(el.dataset.service)return serviceSheet(el.dataset.service);if(el.dataset.page){closeSheet();return go(el.dataset.page)}switch(el.dataset.action){case 'simulate-notification':return showDemoNotification();case 'dismiss-notification':return hideDemoNotification();case 'open-notification':hideDemoNotification();return go('notifications');case 'restart-demo':return restartDemo();case 'switch-fair':return fairSheet();case 'help':return helpSheet();case 'ticket':return ticketSheet();case 'venue':return venueSheet();case 'feedback':return feedbackSheet();case 'qr':return qrSheet('stand');case 'event-qr':return qrSheet('event');case 'preview-announcement':{const title=$('#admin-title')?.value.trim();const body=$('#admin-body')?.value.trim();if(!title||!body)return toast('Başlık ve mesajı doldur.');return showDemoNotification({title,body,audience:state.adminAudience})}case 'start-camera':return startCamera();case 'lookup-code':return lookupCode();case 'close-sheet':return closeSheet();case 'notify-permission':return enableNotifications();case 'open-signings':state.kind='İmza';state.day=1;state.programQuery='';return go('program');case 'open-talks':state.kind='Söyleşi';state.day=1;state.programQuery='';return go('program');case 'open-program':if(state.fair==='ankara')state.kind='İmza';return go('program');case 'open-plan':return go('plan');case 'open-map':return openMapSheet();case 'map-other':return toast('Bu alan gerçek fuar krokisiyle açılacak.')}});
document.addEventListener('input',event=>{if(event.target.id==='search'){state.query=event.target.value;$('#participant-results').innerHTML=participantCards(filteredParticipants())}if(event.target.id==='program-search'){state.programQuery=event.target.value;$('#event-results').innerHTML=programResults()}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeSheet();if((event.key==='Enter'||event.key===' ')&&event.target.dataset.event){event.preventDefault();showEvent(event.target.dataset.event)}if(event.key==='Enter'&&event.target.id==='qr-code')lookupCode()});
$('#sheet-backdrop').addEventListener('click',event=>{if(event.target.id==='sheet-backdrop')closeSheet()});

function passport(){
  const count=stampCount();
  const featured=events().slice(0,3);
  return `<div class="screen"><button class="link-button" data-page="home">← Fuara dön</button><div class="kicker" style="margin-top:12px">İSTEĞE BAĞLI KEŞİF</div><h1 class="page-title">Fuar Pasaportu</h1><p class="page-sub">Etkinliklere katıl, çıkışta küçük bir sürprize yaklaş.</p><div class="passport-progress"><div class="passport-progress-top"><span>KEŞİF DAMGALARI</span><strong>${Math.min(count,3)} / 3</strong></div><div class="stamp-track">${[0,1,2].map(i=>`<span class="stamp ${i<count?'filled':''}">${i<count?'✓':'✳'}</span>`).join('')}</div><p>${count>=3?'Üç farklı etkinliği keşfettin! Bu ekranda ödül teslim bilgisi gösterilebilir.':'Farklı etkinliklerdeki QR kodlarını okut. Her etkinlik bir damga.'}</p></div><button class="primary full" data-action="event-qr">Etkinlik QR kodunu okut →</button>${sectionTitle('Keşfedilecek etkinlikler','program')}${featured.map(e=>`<button class="passport-event" data-event="${e.id}"><span class="${state.stamps.has(e.id)?'checked':''}">${state.stamps.has(e.id)?'✓':'○'}</span><strong>${e.title}</strong><small>${e.time} →</small></button>`).join('')}<div class="quiz-card"><span class="kicker">GÜNÜN SORUSU · İSTEĞE BAĞLI</span><h2>Eylül Fuarcılık hangi yıldan beri fuarlar düzenliyor?</h2><div class="quiz-options">${['1999','2005','2012'].map(answer=>`<button class="chip ${state.quizAnswer===answer?'active':''}" data-quiz="${answer}">${answer}</button>`).join('')}</div>${state.quizAnswer?`<p>${state.quizAnswer==='1999'?'Doğru! Eylül Fuarcılık 1999’dan beri fuarlar düzenliyor.':'Bir ipucu: Resmî organizatör sayfasına göz atabilirsin.'}</p>`:''}</div><p class="muted-note">Ödül fikri konsepttir; kapsamı ve teslim koşulları organizatör tarafından belirlenir. Bu demo QR kodları katılım kanıtı değildir.</p></div>`;
}
function admin(){return `<div class="screen"><button class="link-button" data-page="notifications">← Bildirimlere dön</button><div class="kicker" style="margin-top:12px">ORGANİZATÖR GÖRÜNÜMÜ · DEMO</div><h1 class="page-title">Tek duyuru.<br>Doğru kitle.</h1><p class="page-sub">Eylül ekibi önemli bilgiyi ziyaretçilerin uygulamasına buradan ulaştırabilir.</p><div class="announcement-lead"><small>DUYURU MERKEZİ</small><strong>Program değiştiğinde, herkes aynı bilgiyi zamanında görsün.</strong><p>Bu ekranda duyuru yalnızca ziyaretçi görünümünde önizlenir.</p></div>${sectionTitle('Kime ulaşacak?')}<button class="audience-card ${state.adminAudience==='Tüm ziyaretçiler'?'active':''}" data-admin-audience="Tüm ziyaretçiler"><strong>◉ Tüm ziyaretçiler</strong><small>Giriş, ulaşım ve genel fuar duyuruları</small></button><button class="audience-card ${state.adminAudience==='Planına ekleyenler'?'active':''}" data-admin-audience="Planına ekleyenler"><strong>♡ Planına ekleyenler</strong><small>Belirli etkinliğin takipçileri için hatırlatma</small></button><label class="admin-field"><span>DUYURU BAŞLIĞI</span><input id="admin-title" maxlength="65" value="Ana sahnede program güncellemesi"></label><label class="admin-field"><span>KISA MESAJ</span><textarea id="admin-body" maxlength="160">Bugünkü söyleşi saat 14.30'da başlayacak. Güncel konum: Ana Sahne.</textarea></label><button class="primary full" data-action="preview-announcement">Ziyaretçi görünümünde önizle →</button><p class="muted-note">Bu prototip gerçek ziyaretçilere mesaj göndermez. Canlı kullanımda yetkilendirme, onay ve gönderim kayıtları gerekir.</p></div>`}

